import './chatbot-widget.js';
import type { TimelyChatbot } from './chatbot-widget.js';

/**
 * widget init.
 *
 * 두 모드를 같은 함수로 처리:
 *   - 인증 모드: getAccessToken 콜백 제공 → widget이 필요할 때마다 호출. 401 받으면 자동 재호출.
 *   - 게스트 모드: getAccessToken 생략 → /widget/guest-jwt 자동 호출 (프로젝트 토글 ON 필요)
 *
 * @example 인증 모드
 *   TimelyChatbot.init({
 *     apiKey: "tgc_...",
 *     getAccessToken: async () => {
 *       const r = await fetch("/api/widget-jwt").then(r => r.json());
 *       return r.jwt;
 *     },
 *   });
 *
 * @example 게스트 모드
 *   TimelyChatbot.init({ apiKey: "tgc_..." });
 */
export interface InitOptions {
  /** 프로젝트 API key. 클라 노출 OK (Origin 화이트리스트로 보호). */
  apiKey: string;
  /**
   * 호스트가 end-user JWT를 반환하는 콜백.
   * 처음 chat 호출 직전 + 401 받은 후 widget이 자동 호출. 호스트는 매번 fresh 토큰 반환.
   * 생략 시 게스트 모드.
   */
  getAccessToken?: () => Promise<string>;
  /** API base URL. 미지정 시 빌드 default(VITE_API_BASE_URL) → fallback localhost:3410. */
  apiBaseUrl?: string;
  /** 마운트 위치. default: <body>. */
  mountTo?: HTMLElement;
}

export interface WidgetHandle {
  /** widget element 제거. */
  destroy: () => void;
}

const BROWSER_ID_STORAGE_KEY = 'timely-chatbot-bid';
const DEFAULT_API_BASE_URL =
  (import.meta.env.VITE_API_BASE_URL as string | undefined) ??
  'http://localhost:3410';

declare global {
  interface Window {
    TimelyChatbot?: { init: (opts: InitOptions) => WidgetHandle };
  }
}

function ensureBrowserId(): string {
  try {
    const cached = localStorage.getItem(BROWSER_ID_STORAGE_KEY);
    if (cached) return cached;
    const next = `tc-${crypto.randomUUID()}`;
    localStorage.setItem(BROWSER_ID_STORAGE_KEY, next);
    return next;
  } catch {
    return `tc-${crypto.randomUUID()}`;
  }
}

function init(opts: InitOptions): WidgetHandle {
  if (!opts.apiKey) throw new Error('TimelyChatbot.init: apiKey가 필요합니다');
  const el = document.createElement('timely-chatbot') as TimelyChatbot;
  el.apiBaseUrl = opts.apiBaseUrl ?? DEFAULT_API_BASE_URL;
  el.apiKey = opts.apiKey;
  el.browserId = ensureBrowserId();
  if (opts.getAccessToken) el.getAccessToken = opts.getAccessToken;
  (opts.mountTo ?? document.body).appendChild(el);

  return {
    destroy: () => el.remove(),
  };
}

window.TimelyChatbot = { init };
export { init };
