// marked: GFM(table/strikethrough) + breaks(개행 → <br>)로 LLM 응답 친화 설정
marked.setOptions({ gfm: true, breaks: true });

/** assistant 응답을 markdown → HTML → DOMPurify sanitize. */
/**
 * 호스트 페이지에서 본문 텍스트 추출 — LLM의 get_current_page 도구 결과로 사용.
 *
 * - body를 deep clone해 위젯/스크립트/네비/푸터 제거 후 article 또는 main 우선
 * - innerText로 화면에 보이는 텍스트만 (display:none 자동 제외)
 * - 50KB 한도 — 더 크면 잘라냄.
 */
const PAGE_CONTEXT_MAX_CHARS = 50_000;
function extractPageText(): string {
  try {
    const cloned = document.body.cloneNode(true) as HTMLElement;
    cloned
      .querySelectorAll(
        'script, style, noscript, iframe, nav, footer, header, aside, [aria-hidden="true"], timely-chatbot',
      )
      .forEach((el) => el.remove());
    const article = cloned.querySelector('article');
    const main = cloned.querySelector('main');
    const root: HTMLElement =
      article instanceof HTMLElement
        ? article
        : main instanceof HTMLElement
          ? main
          : cloned;
    const raw = (root.innerText ?? root.textContent ?? '').toString();
    const normalized = raw
      .replace(/ /g, ' ')
      .split(/\n+/)
      .map((line) => line.replace(/[ \t]+/g, ' ').trim())
      .filter((line) => line.length > 0)
      .join('\n');
    if (normalized.length > PAGE_CONTEXT_MAX_CHARS) {
      return (
        normalized.slice(0, PAGE_CONTEXT_MAX_CHARS) +
        `\n\n…(이하 ${normalized.length - PAGE_CONTEXT_MAX_CHARS}자 생략)`
      );
    }
    return normalized;
  } catch {
    return '';
  }
}

function renderMarkdown(text: string): string {
  const html = marked.parse(text, { async: false }) as string;
  return DOMPurify.sanitize(html, {
    // 안전한 inline tag만 허용. <script>, <iframe>, on* 핸들러 모두 차단.
    ALLOWED_TAGS: [
      'p', 'br', 'strong', 'em', 'b', 'i', 'u', 's', 'del',
      'a', 'code', 'pre', 'blockquote',
      'ul', 'ol', 'li',
      'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
      'table', 'thead', 'tbody', 'tr', 'th', 'td',
      'hr', 'span', 'div',
    ],
    ALLOWED_ATTR: ['href', 'title', 'target', 'rel', 'class'],
  });
}

